def main(query: str, plan: object, docs: str) -> dict:
    import json
    import re
    from urllib.parse import parse_qsl, urlencode, urlunsplit

    catalog = {
        1: ("/baseData/baseLine/getBaseLineList", "获取线路列表", "lineName:s"),
        2: ("/baseData/baseStation/getBaseStationList", "获取车站列表", "lineId!:s isFilter:b"),
        3: ("/baseData/baseSection/getBaseSectionList", "获取区间列表", "lineId!:s isFilterSection:b"),
        4: ("/baseData/baseTransfer/getBaseTransferStationList", "获取换乘车站详情列表", "stationName:s"),
        5: ("/baseData/baseRoute/getBaseRouteList", "获取交路列表", "lineId!:s startName:s lastName:s routeDir:i"),
        6: ("/baseData/baseRunScale/getRunScaleList", "获取运行标尺列表", "lineId!:s scaleName:s"),
        7: ("/baseData/baseStopScale/getStopScaleList", "获取停站标尺列表", "lineId!:s scaleName:s"),
        8: ("/baseData/baseTrack/getBaseTrackList", "获取股道列表", "lineId!:s stationId:s trackFunctionType:s"),
        9: ("/baseData/baseVehicle/getBaseVehicleList", "获取车辆列表", "lineId!:s"),
        10: ("/baseNetwork/getAllLineVehicleType", "获取线路车辆类型集合", "cityName:s"),
        11: ("/baseNetwork/getBaseDataTypeList", "获取全部基础数据类型列表", ""),
        12: ("/baseNetwork/getAllNetworkInfoList", "获取所有线网信息列表", ""),
        13: ("/operatePlan/manage/queryPlanList", "运输方案分页列表查询",
            "planLevelType!:i operatePlanName:s lineName:s lineId:s planPeriodType:i "
            "planPassengerType:i createDate:s pageNum:i pageSize:i"),
        14: ("/operatePlan/basic/getOperatePlanPass", "获取客流数据",
            "networkPlanId!:s lineId!:s startTime:s endTime:s startAndEndTime:s "
            "transectName:s sectionName:s spaceTimeType:i queryTimeSpan!:i isInversionControl:b"),
        15: ("/trainDiagramSchedule/manageOperation/queryDiagramList", "运行图管理分页列表",
            "diagramLevelType!:i diagramName:s lineName:s lineId:s diagramPeriodType:i "
            "diagramUseType:i diagramSaveType:i createDate:s pageNum:i pageSize:i"),
        17: ("/lastTrain/accessibility/getLoadLineTrainDiagram", "获取加载的线路运行图", ""),
        18: ("/lastTrain/accessibility/queryLastTrainAccessibilityInfo", "查询末班车可达性",
            "queryType!:i startLineName:s startLineId:s startStationName:s "
            "lastLineName:s lastLineId:s lastStationName:s "
            "inLineName:s inLineId:s inStationName:s inTime:s "
            "outLineName:s outLineId:s outStationName:s outTime:s")
    }

    def fail(message: str) -> None:
        raise ValueError(message)

    if not isinstance(query, str) or not query.strip() or len(query) > 2000:
        fail("请提供不超过2000字符的问题。")
    if not isinstance(plan, dict) or set(plan) != {"接口编号", "参数"}:
        fail("模型structured_output必须只包含接口编号和参数。")
    raw_no = plan.get("接口编号")
    if (isinstance(raw_no, bool) or not isinstance(raw_no, (int, float))
            or int(raw_no) != raw_no):
        fail("接口编号必须是整数。")
    api_no = int(raw_no)
    if api_no == 0:
        fail("没有选出可执行的单个接口，本次不调用。")
    if api_no not in catalog:
        fail("接口编号不在获准的只读目录中，本次不调用。")
    path, name, spec = catalog[api_no]
    if (not isinstance(docs, str) or not docs.strip()
            or (path not in docs and name not in docs
                and re.search(r"(?m)^#{2,3}\s*" + str(api_no) + r"\.\s", docs) is None)):
        fail("选中接口未出现在本次召回文档中，本次不调用。")
    raw_params = plan.get("参数")
    if not isinstance(raw_params, str) or len(raw_params) > 4000:
        fail("参数必须是不超过4000字符的字符串。")
    raw_params = raw_params.strip()
    if raw_params in ("无", "无参数", "none", "null"):
        raw_params = ""
    if raw_params.startswith("?"):
        raw_params = raw_params[1:]
    if "://" in raw_params or "#" in raw_params:
        fail("参数字段不能包含URL、路径片段或说明文字。")
    try:
        pairs = ([] if not raw_params else
                 parse_qsl(raw_params, keep_blank_values=True,
                           strict_parsing=True, max_num_fields=30))
    except ValueError:
        fail("请求查询参数格式不正确或数量过多。")
    params_text = {}
    for key, value in pairs:
        if key in params_text:
            fail("请求参数存在重复键，本次不调用。")
        params_text[key] = value

    fields, required = {}, []
    for token in spec.split():
        key, kind = token.split(":")
        if key.endswith("!"):
            required.append(key[:-1])
        fields[key.rstrip("!")] = kind
    if set(params_text) - set(fields):
        fail("请求包含所选接口未定义的参数，本次不调用。")
    missing = [key for key in required if not params_text.get(key)]
    if missing:
        fail("缺少必填参数：" + "、".join(missing) + "；不会调用其他接口补齐。")

    params = {}
    for key, value in params_text.items():
        kind = fields[key]
        if kind == "s":
            if not value or len(value) > 500 or any(ord(char) < 32 for char in value):
                fail("字符串参数为空、过长或包含控制字符：" + key)
            params[key] = value
        elif kind == "i":
            if len(value) > 20 or not re.fullmatch(r"-?\d+", value):
                fail("整数参数格式不正确：" + key)
            params[key] = int(value)
        elif kind == "b":
            if value.lower() not in ("true", "false"):
                fail("布尔参数必须是true或false：" + key)
            params[key] = value.lower() == "true"

    labels = {
        "lineId": "线路编号", "stationId": "车站编号",
        "networkPlanId": "已加载方案编号", "startLineId": "起始线路编号",
        "lastLineId": "终到线路编号", "inLineId": "进站线路编号",
        "outLineId": "出站线路编号"
    }
    for key, label in labels.items():
        if key in params:
            value = str(params[key])
            markers = (key + "=", key + "：", label + "=", label + "：",
                       label + "为", label + "是")
            explicit = False
            for marker in markers:
                needle = marker + value
                position = query.find(needle)
                if position >= 0:
                    end = position + len(needle)
                    if (end == len(query) or
                            query[end] not in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-"):
                        explicit = True
                        break
            if not explicit:
                fail("请明确提供" + label + "（例如“" + label +
                     "=真实编号”）；不能从名称或文档样例猜编号。")
    enums = {
        "planLevelType": {0, 1}, "diagramLevelType": {0, 1},
        "spaceTimeType": {0, 1}, "diagramUseType": {0, 1},
        "diagramSaveType": {0, 1}, "diagramPeriodType": {0, 1, 2, 3, 4},
        "queryType": {0, 1, 2, 3}
    }
    for key, values in enums.items():
        if key in params and params[key] not in values:
            fail("参数枚举值不合法：" + key)

    paged = path in ("/operatePlan/manage/queryPlanList",
                     "/trainDiagramSchedule/manageOperation/queryDiagramList")
    if paged:
        params.setdefault("pageNum", 1)
        params.setdefault("pageSize", 20)
        if params["pageNum"] < 1 or not 1 <= params["pageSize"] <= 100:
            fail("页码至少为1，每页条数为1至100；本轮只请求一页。")
    if "queryTimeSpan" in params and params["queryTimeSpan"] < 1:
        fail("客流粒度必须为正整数。")
    if path == "/lastTrain/accessibility/queryLastTrainAccessibilityInfo":
        groups = {
            0: ["inLineName", "inStationName", "inTime"],
            1: ["startLineName", "startStationName", "lastLineName", "lastStationName"],
            2: ["outLineName", "outStationName"],
            3: ["inLineName", "inStationName"]
        }
        missing = [key for key in groups[params["queryType"]] if not params.get(key)]
        if missing:
            fail("该查询维度还需要：" + "、".join(missing))

    base_path = "/itosItpass-qd"
    encoded = urlencode({key: str(value).lower() if type(value) is bool else value
                         for key, value in params.items()})
    normalized_url = urlunsplit(("http", "172.27.175.131",
                                 base_path + path, encoded, ""))
    request = {"接口编号": api_no, "接口名称": name, "接口路径": path, "请求方法": "GET",
               "请求参数": params, "单页请求": paged}
    return {"url": normalized_url,
            "request_json": json.dumps(request, ensure_ascii=False)}

def main(status_code: float, content: str, request_json: str) -> dict:
    import json
    from datetime import datetime, timezone

    request = json.loads(request_json)
    if not isinstance(request, dict) or not isinstance(request.get("接口路径"), str):
        raise ValueError("request_json绑定错误。")
    result = {
        "状态": "失败", "消息": "", "接口名称": request.get("接口名称", ""),
        "接口路径": request["接口路径"], "请求参数": request.get("请求参数", {}),
        "数据": None, "本次记录数": None, "分页信息": None,
        "单页请求": request.get("单页请求", False),
        "响应时间": datetime.now(timezone.utc).isoformat(),
        "展示截断": False, "提示": []
    }

    def fail(message: str) -> None:
        raise ValueError(message)

    try:
        if (isinstance(status_code, bool) or
                not isinstance(status_code, (int, float)) or
                not 200 <= status_code < 300 or int(status_code) != status_code):
            fail("接口HTTP状态异常，本次没有可用结果，未重试或调用其他接口。")
        if not isinstance(content, str) or not content.strip():
            fail("接口响应为空，不能解释为0条数据。")
        if len(content) > 2000000:
            fail("响应超过本节点处理上限，未截断后冒充完整结果。")
        payload = json.loads(content, parse_constant=lambda value: fail("响应包含非法数值。"))
        if not isinstance(payload, dict) or payload.get("success") is not True:
            fail("接口未明确返回success=true，本次没有可用结果。")
        data = payload.get("data")
        if not isinstance(data, (dict, list)):
            fail("接口data不是文档约定的对象或数组，请检查响应契约。")
        if result["单页请求"]:
            if (not isinstance(data, dict) or not isinstance(data.get("list"), list)
                    or not isinstance(data.get("pageInfo"), dict)):
                fail("分页接口应返回pageInfo和list；本次响应结构不符。")
            result["本次记录数"] = len(data["list"])
            result["分页信息"] = data["pageInfo"]
            result["提示"].append("只取得本次请求页，不自动翻页；本次记录数不是全量总数。")
        elif isinstance(data, list):
            result["本次记录数"] = len(data)
        result["数据"] = data
        result["状态"] = "成功"
        result["消息"] = "已取得本次单接口响应。"
        result["提示"].append("保留接口原始口径；返回记录数不是去重数、客运站数或跨页总数。")
    except (ValueError, TypeError, RecursionError) as exc:
        result["数据"] = None
        result["本次记录数"] = None
        result["分页信息"] = None
        result["消息"] = ("接口响应不是有效JSON，本次未取得数据。"
                        if isinstance(exc, (json.JSONDecodeError, RecursionError))
                        else str(exc))

    changed = [False]

    def preview(value: object, depth: int = 0) -> object:
        if depth > 5 and isinstance(value, (dict, list)):
            changed[0] = True
            return "【嵌套内容未展示，完整数据在result中】"
        if isinstance(value, list):
            changed[0] |= len(value) > 20
            return [preview(item, depth + 1) for item in value[:20]]
        if isinstance(value, dict):
            changed[0] |= len(value) > 40
            return {key: preview(item, depth + 1) for key, item in list(value.items())[:40]}
        if isinstance(value, str) and len(value) > 500:
            changed[0] = True
            return value[:500] + "【文本未全部展示】"
        return value

    fact = {key: preview(value) for key, value in result.items()}
    if len(json.dumps(fact, ensure_ascii=False)) > 12000:
        fact["数据"] = "【响应较大，模型预览已省略；完整数据在result中】"
        fact["分页信息"] = None
        changed[0] = True
    result["展示截断"] = changed[0]
    fact["展示截断"] = changed[0]
    facts = json.dumps(fact, ensure_ascii=False, separators=(",", ":"))
    if len(facts) > 12000:
        raise ValueError("事实包仍过长，请调整本地展示策略，不重新请求接口。")
    return {"facts": facts, "result": result}
